def current_runtime_projection(result):
    for name, replacements in CURRENT_RUNTIME_PROJECTION.items():
        for before, after in replacements:
            if result[name] != before:
                raise ValueError("CURRENT_RUNTIME_BASE_SOURCE_DRIFT: " + name)
            result[name] = after
    return result
